SELECT d.id, d.order_id, d.order_no, d.package_no, d.express_code, d.express_name, d.tracking_number, d.delivery_type, d.delivery_time, d.remark, d.created_at, d.updated_at, o.consignee, o.phone, o.region, o.detail_address, o.remark AS buyer_remark, o.order_status, o.sign_status FROM order_delivery d JOIN orders o ON o.id = d.order_id AND o.is_deleted = 0 WHERE d.is_deleted = 0
AND d.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND d.tracking_number LIKE CONCAT('%', #{trackingNumber}, '%')
AND d.express_code = #{expressCode}
AND d.delivery_type = #{deliveryType}
ORDER BY d.created_at DESC, d.id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM order_delivery d JOIN orders o ON o.id = d.order_id AND o.is_deleted = 0 WHERE d.is_deleted = 0
AND d.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND d.tracking_number LIKE CONCAT('%', #{trackingNumber}, '%')
AND d.express_code = #{expressCode}
AND d.delivery_type = #{deliveryType}
